import os
import openpyxl

out_path = os.environ['OUT_XLSX']
wb = openpyxl.load_workbook(out_path)
ws = wb['Sheet1']

# Read all data rows (row 2 onwards)
data_rows = []
for row in ws.iter_rows(min_row=2, max_row=ws.max_row, min_col=1, max_col=5, values_only=False):
    e_val = row[4].value  # Column E
    if e_val is not None:
        e_str = str(e_val)
        if e_str.startswith('Z1') or e_str.startswith('X1'):
            continue  # Skip this row (delete it)
    data_rows.append([cell.value for cell in row])

# Clear all data rows first
for row in ws.iter_rows(min_row=2, max_row=ws.max_row, min_col=1, max_col=5):
    for cell in row:
        cell.value = None

# Write back the kept rows
for i, row_data in enumerate(data_rows):
    for j, val in enumerate(row_data):
        ws.cell(row=i+2, column=j+1, value=val)

wb.save(out_path)
print(f'Kept {len(data_rows)} rows')
for r in data_rows:
    print(r)
